def legacy_name(relative):
    return 'experiments/' + relative[5:] if relative.startswith('data/') else relative

def source_path(path):
    path = Path(path)
    candidate = path if path.is_absolute() else ROOT / path
    try: relative = candidate.resolve().relative_to(ROOT).as_posix()
    except ValueError: return path
    target = SOURCE_MOVES.get(relative, SOURCE_MOVES.get(legacy_name(relative)))
    return ROOT / target if target is not None else path

def source_directory(path):
    path = Path(path)
    candidate = path if path.is_absolute() else ROOT / path
    try: relative = candidate.resolve().relative_to(ROOT).as_posix()
    except ValueError: return path
    target = SOURCE_DIRECTORIES.get(relative, SOURCE_DIRECTORIES.get(legacy_name(relative)))
    return ROOT / target if target is not None else path

def experiment_directory(source):
    source = Path(source).resolve()
    relative = source.relative_to(ROOT).as_posix()
    previous = next((old for old, new in SOURCE_MOVES.items() if new == relative), None)
    if previous is not None and previous.startswith('experiments/'):
        return (ROOT / 'data' / previous[len('experiments/'):]).parent
    return (ROOT / previous).parent if previous is not None else source.parent
